"""Offline disclosure contracts for the sources generated by init."""

import pytest

from guardian.onboarding import _share_source


@pytest.mark.parametrize("endpoint_env", ["BITCOIN_MAINNET_URL", "CUSTOM_ESPLORA_URL"])
@pytest.mark.parametrize("credential_env", [None, "ESPLORA_API_KEY"])
def test_esplora_discloses_addresses_to_configured_host(endpoint_env, credential_env):
    source = {"adapter": "esplora", "enabled": True, "endpoint_env": endpoint_env}
    if credential_env is not None:
        source["credential_env"] = credential_env
    row = _share_source("bitcoin-reader", source)
    assert row["sends_addresses"] is True
    assert row["recipient"] == f"the Esplora host named by {endpoint_env}"
    assert "Bitcoin addresses are sent" in row["data"]
    assert "keyless and keyed reads" in row["data"]
    assert "Xpubs are never sent" in row["data"]
    assert "credential_missing" not in row["data"]


@pytest.mark.parametrize("credential_env", [None, "HELIUS_API_KEY"])
def test_helius_discloses_no_address_queries(credential_env):
    source = {"adapter": "helius_parsed_events", "enabled": True, "endpoint_env": "HELIUS_URL"}
    if credential_env is not None:
        source["credential_env"] = credential_env
    row = _share_source("helius-parser", source)
    assert row["sends_addresses"] is False
    assert row["recipient"] == "Helius at the host named by HELIUS_URL"
    assert "not called" in row["data"]
    assert "address is not sent" in row["data"]
    assert "credential_missing" not in row["data"]


@pytest.mark.parametrize("adapter,sends_addresses", [
    ("evm_rpc", True),
    ("solana_rpc", True),
    ("tron_grid", True),
    ("aptos_rest", False),
    ("cosmos_rest", False),
    ("sui_graphql", False),
    ("toncenter_v3", False),
])
def test_other_keyless_init_sources_match_read_support(adapter, sends_addresses):
    source = {"adapter": adapter, "enabled": True, "endpoint_env": "CUSTOM_READER_URL"}
    if adapter == "tron_grid":
        # Init declares this optional key even when the operator has none.
        source["credential_env"] = "TRON_PRO_API_KEY"
    row = _share_source("reader", source)
    assert row["sends_addresses"] is sends_addresses
    assert "CUSTOM_READER_URL" in row["recipient"]
    if sends_addresses:
        assert "Wallet address is sent" in row["data"]
    else:
        assert "address is not sent" in row["data"]
        assert "unsupported" in row["data"]


def test_routescan_discloses_default_origin_and_override():
    row = _share_source("routescan", {
        "adapter": "routescan",
        "credential_env": "ROUTESCAN_API_KEY",
        "enabled": True,
        "endpoint_env": "ROUTESCAN_API_BASE",
    })
    assert row["sends_addresses"] is True
    assert "https://api.routescan.io" in row["recipient"]
    assert "ROUTESCAN_API_BASE" in row["recipient"]
    assert "https://api.routescan.io" in row["data"]
    assert "ROUTESCAN_API_BASE" in row["data"]
    assert "credential_missing" not in row["data"]



